<script setup lang="ts">
withDefaults(defineProps<{ id: string; label: string; placeholder?: string; modelValue?: string; helperText?: string; errorText?: string; successText?: string; disabled?: boolean; loading?: boolean; required?: boolean; readOnly?: boolean; dir?: 'rtl' | 'ltr' | 'auto'; rows?: number; maxlength?: number; size?: 'small' | 'medium' | 'large' | 'xlarge'; labelPlacement?: 'inside' | 'outside' }>(), { dir: 'rtl', rows: 4, size: 'medium', labelPlacement: 'outside' });
const emit = defineEmits<{ 'update:modelValue': [value: string] }>()
</script>
<template>
  <div class="norato-textarea-group" :data-size="size" :data-label-placement="labelPlacement" :aria-busy="loading || undefined" :class="{ 'is-invalid': errorText, 'is-loading': loading }"><label class="norato-textarea__label" :for="id">{{ label }}<span v-if="required" aria-hidden="true"> *</span></label><textarea class="norato-textarea" :id="id" :dir="dir" :rows="rows" :maxlength="maxlength" :value="modelValue" :placeholder="placeholder" :disabled="disabled || loading" :readonly="readOnly" :required="required" :aria-invalid="errorText ? 'true' : undefined" :aria-describedby="[helperText && `${id}-helper`, errorText && `${id}-error`, successText && `${id}-success`, maxlength && `${id}-count`, loading && `${id}-loading`].filter(Boolean).join(' ') || undefined" @input="emit('update:modelValue', ($event.target as HTMLTextAreaElement).value)" /><p v-if="loading" class="norato-textarea__message" :id="`${id}-loading`" role="status" aria-live="polite">در حال بارگذاری</p><p v-if="helperText" class="norato-textarea__message" :id="`${id}-helper`">{{ helperText }}</p><p v-if="errorText" class="norato-textarea__message norato-textarea__error" :id="`${id}-error`" role="alert">{{ errorText }}</p><p v-if="successText && !errorText" class="norato-textarea__message" :id="`${id}-success`" role="status">{{ successText }}</p><p v-if="maxlength" class="norato-textarea__message" :id="`${id}-count`" aria-live="polite">{{ (modelValue ?? '').length }} / {{ maxlength }}</p></div>
</template>
